// GENERATED by packages/mcp/scripts/build.mjs from src/lib/match.mjs. Do not edit here.
// Answers "will this hotel (or campground) take my dog, and what will it cost?"
// from the structured policy. Every check reports whether the policy settles it
// or not, so an assistant can say "yes", "no" or "ask the hotel" honestly.

import { STAY } from "../stay.mjs";

const PER_PET = new Set(["per_pet_per_night", "per_pet_per_stay", "per_pet"]);
const PER_NIGHT = new Set([
  "per_night",
  "per_pet_per_night",
  "per_room_per_night",
]);

/**
 * Estimated pet fee for a stay. Returns { amount, upTo, known, note }:
 * amount is null when the policy doesn't settle it; upTo means the policy
 * states a maximum, so the real charge can be lower.
 */
export function estimateFee(fee, { dogs = 1, nights = 1 } = {}) {
  if (!fee)
    return {
      amount: null,
      upTo: false,
      known: false,
      note: "No fee stated in the policy.",
    };
  if (fee.amount === 0) {
    if (fee.freePets && dogs > fee.freePets)
      return {
        amount: null,
        upTo: false,
        known: false,
        note: `${fee.freePets === 1 ? "First pet" : `First ${fee.freePets} pets`} free; check the policy for additional pets.`,
      };
    return { amount: 0, upTo: false, known: true, note: "No pet fee." };
  }
  // A basis the source leaves open settles the total only when the open part
  // cannot change it: one night for "per pet", one dog and one night otherwise.
  if (
    (fee.basis === "per_pet" && nights > 1) ||
    (fee.basis === "unstated" && (dogs > 1 || nights > 1))
  )
    return {
      amount: null,
      upTo: false,
      known: false,
      note: `The policy gives ${fee.basis === "per_pet" ? `$${fee.amount} per pet` : `a $${fee.amount} pet fee`} without saying ${fee.basis === "per_pet" ? "whether it is per night or per stay" : "per night, per stay or per pet"}.`,
    };
  if (fee.petsUnstated && dogs > 1)
    return {
      amount: null,
      upTo: false,
      known: false,
      note: `The policy does not say whether the $${fee.amount} is per pet.`,
    };
  let amount = fee.amount;
  if (PER_PET.has(fee.basis)) amount *= dogs;
  if (PER_NIGHT.has(fee.basis)) amount *= nights;
  const capped = fee.capPerStay != null && amount > fee.capPerStay;
  if (capped) amount = fee.capPerStay;
  return {
    amount,
    upTo: Boolean(fee.upTo),
    known: true,
    note: capped ? `Capped at $${fee.capPerStay} per stay.` : null,
  };
}

/**
 * Whether a dog of this weight fits the policy: "ok", "too_heavy", "approval"
 * (over a limit the business lifts with its approval), "combined" (the
 * heaviest dog fits a limit for all the dogs together, but their total is not
 * known) or "unknown". weightLb is the heaviest dog's weight.
 */
export function checkWeight(facts, weightLb, dogs = 1) {
  if (weightLb == null) return "ok";
  const w = facts.weightLimitLb;
  if (!w || w.value === "varies") return "unknown";
  if (w.value === null) return "ok";
  if (weightLb > w.value) return w.byApproval ? "approval" : "too_heavy";
  // Every dog weighs no more than the heaviest, so this many such dogs settle it.
  return !w.combined || weightLb * dogs <= w.value ? "ok" : "combined";
}

/** Whether this many dogs fits the policy: "ok", "too_many", "approval" or "unknown". */
export function checkCount(facts, dogs) {
  const m = facts.maxPets;
  if (!m) return dogs === 1 ? "ok" : "unknown";
  if (m.value === null || dogs <= m.value) return "ok";
  return m.byApproval ? "approval" : "too_many";
}

/**
 * Sorts a hotel or campground into "match" (the policy says yes on every point
 * asked), "possible" (nothing rules it out, but something needs a call) or
 * "excluded".
 */
export function evaluateHotel(
  place,
  { weightLb, dogs = 1, nights = 1, maxTotalFee } = {},
) {
  const stay = STAY[place.type] ?? STAY.lodging;
  const reasons = [];
  const status = place.answer.status;
  if (status === "no")
    return {
      verdict: "excluded",
      reasons: ["Pets are not allowed."],
      fee: null,
    };

  let verdict = "match";
  const soften = (why) => {
    if (verdict === "match") verdict = "possible";
    reasons.push(why);
  };

  if (status === "varies")
    soften(
      `The ${stay.place} decides whether it accepts pets; confirm it is pet-friendly.`,
    );

  const weight = checkWeight(place.facts, weightLb, dogs);
  if (weight === "too_heavy")
    return {
      verdict: "excluded",
      reasons: [
        `Weight limit is ${place.facts.weightLimitLb.value} lb${place.facts.weightLimitLb.combined ? " for all pets combined" : ""}.`,
      ],
      fee: null,
    };
  if (weight === "combined")
    soften(
      `The ${stay.place} allows up to ${place.facts.weightLimitLb.value} lb for all pets combined; check your dogs' total weight.`,
    );
  if (weight === "unknown")
    soften(
      `The policy does not settle the weight limit for this ${stay.place}.`,
    );
  if (weight === "approval")
    soften(
      `Dogs over ${place.facts.weightLimitLb.value} lb need the ${stay.place}'s approval.`,
    );

  const count = checkCount(place.facts, dogs);
  if (count === "too_many")
    return {
      verdict: "excluded",
      reasons: [
        `At most ${place.facts.maxPets.value} ${place.facts.maxPets.value === 1 ? "pet" : "pets"} per ${stay.unit}.`,
      ],
      fee: null,
    };
  if (count === "unknown")
    soften(`The policy does not say whether ${dogs} dogs are allowed.`);
  if (count === "approval")
    soften(
      `More than ${place.facts.maxPets.value} ${place.facts.maxPets.value === 1 ? "pet needs" : "pets need"} the ${stay.place}'s approval.`,
    );

  const fee = estimateFee(place.facts.fee?.value, { dogs, nights });
  if (!fee.known) soften(fee.note);
  if (maxTotalFee != null && fee.known) {
    if (!fee.upTo && fee.amount > maxTotalFee)
      return {
        verdict: "excluded",
        reasons: [
          `Pet fee of $${fee.amount} is over the $${maxTotalFee} budget.`,
        ],
        fee,
      };
    if (fee.upTo && fee.amount > maxTotalFee)
      soften(
        `Pet fee is up to $${fee.amount}; it may or may not fit the $${maxTotalFee} budget.`,
      );
  }

  if (place.facts.dogsAllowed?.inheritedFrom)
    reasons.push(`Brand policy; not yet confirmed with this ${stay.place}.`);
  return { verdict, reasons, fee };
}

/** Plain-English fee line for a stay, e.g. "Up to $80 for 2 nights". */
export function feeLine(fee, { nights = 1 } = {}) {
  if (!fee) return "Fee not settled by the policy";
  if (!fee.known) return fee.note;
  if (fee.amount === 0) return "No pet fee";
  const span = nights === 1 ? "1 night" : `${nights} nights`;
  return `${fee.upTo ? "Up to " : ""}$${fee.amount} for ${span}${fee.note ? ` (${fee.note.replace(/\.$/, "")})` : ""}`;
}

/** Great-circle distance in miles. */
export function miles(a, b) {
  const r = Math.PI / 180;
  const x =
    Math.sin(((b.lat - a.lat) * r) / 2) ** 2 +
    Math.cos(a.lat * r) *
      Math.cos(b.lat * r) *
      Math.sin(((b.lon - a.lon) * r) / 2) ** 2;
  return 7917.6 * Math.asin(Math.sqrt(x));
}
